// Normalization, Schema Validation and Deduplication for Live Meta Ads
const items = $input.all();
const seenIds = new Set();
const seenHashes = new Set();
const normalizedList = [];
const skipped = [];

function cleanText(str) {
  if (!str) return '';
  return String(str)
    .replace(/<[^>]+>/g, ' ')
    .replace(/[\u200B\u00A0]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

items.forEach((item, idx) => {
  const raw = item.json;
  const adId = String(raw.ad_archive_id || raw.adArchiveID || raw.adArchiveId || raw.id || `UNKNOWN_${idx}`);
  const pageName = cleanText(raw.page_name || raw.pageName || 'MySivi');
  const snapshot = raw.snapshot || {};
  const cards = snapshot.cards || [];
  const firstCard = cards.length > 0 ? cards[0] : {};

  let bodyText = snapshot.body || firstCard.body || raw.body || '';
  if (typeof bodyText === 'object') bodyText = bodyText.text || '';
  bodyText = cleanText(bodyText);

  const rawTitle = cleanText(snapshot.title || firstCard.title || raw.title || raw.headline || '');
  const cta = cleanText(snapshot.ctaText || snapshot.cta_text || snapshot.ctaType || firstCard.ctaText || 'Install now');

  // Check for empty copy
  if (!bodyText && !rawTitle) {
    skipped.push({ adId, reason: 'Empty copy and headline' });
    return;
  }

  // Content hash for deduplication
  const hash = `${pageName.toLowerCase()}|${rawTitle.toLowerCase()}|${bodyText.slice(0, 150).toLowerCase()}`;
  if (seenIds.has(adId) || seenHashes.has(hash)) {
    skipped.push({ adId, reason: 'Duplicate ad ID or identical copy content' });
    return;
  }

  seenIds.add(adId);
  seenHashes.add(hash);

  // Extract Hook and Headline
  const lines = bodyText.split(/[.!?\n]\s+/);
  const hook = lines[0] ? lines[0].trim() : (rawTitle || 'No hook detected');
  const headline = rawTitle || hook.slice(0, 50);

  const imageUrls = (snapshot.images || []).map(i => i.original_image_url || i.originalImageUrl || i.url).filter(Boolean);
  const videoUrls = (snapshot.videos || []).map(v => v.video_hd_url || v.videoHdUrl || v.url).filter(Boolean);
  if (firstCard.videoHdUrl) videoUrls.push(firstCard.videoHdUrl);
  if (firstCard.videoPreviewImageUrl) imageUrls.push(firstCard.videoPreviewImageUrl);

  normalizedList.push({
    internal_id: `MYSIVI-AD-${String(normalizedList.length + 1).padStart(3, '0')}`,
    ad_id: adId,
    page_name: pageName,
    ad_library_url: raw.ad_library_url || `https://www.facebook.com/ads/library/?id=${adId}`,
    primary_text: bodyText,
    hook: hook,
    headline: headline,
    description: cleanText(snapshot.caption || ''),
    cta: cta,
    landing_page_url: snapshot.linkUrl || snapshot.link_url || 'https://sivi.ai',
    image_urls: imageUrls,
    video_urls: videoUrls,
    media_type: videoUrls.length > 0 ? 'video' : (imageUrls.length > 1 ? 'carousel' : (imageUrls.length > 0 ? 'image' : 'text_only')),
    start_date: raw.start_date || raw.startDateFormatted || 'Unavailable',
    is_active: raw.is_active !== false
  });
});

return normalizedList.map(ad => ({ json: ad }));

