// Deterministic Heuristic AI Analyzer (Mock Mode & Fallback)
const rawInput = $input.first().json;
const ad = rawInput.ad || rawInput;

const text = String(ad.primary_text || ad.body || '').toLowerCase();
const headline = String(ad.headline || '').toLowerCase();
const hook = String(ad.hook || ad.headline || 'No hook detected');
const body = String(ad.primary_text || ad.body || '');
const cta = String(ad.cta || 'Install now');
const internalId = String(ad.internal_id || 'MYSIVI-AD-001');
const adId = String(ad.ad_id || ad.ad_archive_id || ad.adArchiveID || '');

// Check for unreplaced dynamic creative placeholders
const isPlaceholderError = text.includes('{{') || headline.includes('{{') || hook.includes('{{');

let angle = 'Affordable AI Education & Regional Localization';
let usp = 'AI conversational tutor with localized guidance starting at just ₹1.';
let hScore = 8.5, mScore = 9.0, vScore = 8.0, aScore = 8.5, spScore = 6.0, cScore = 7.5, eScore = 8.0, dScore = 8.5;

