let techniques = '₹1 micro-trial price anchoring, mother-tongue comfort, and instant accessibility.';
let strengths = ['Compelling ₹1 trial stopping power', 'Localized regional reassurance', 'Direct Install CTA'];
let weaknesses = ['Lacks student video testimonials in ad copy', 'Landing page URL divergence'];
let suggestions = ['Add video of regional student speaking fluently', 'Include PlayStore rating badge'];
let summary = 'Direct acquisition ad targeting Indian learners with low-friction ₹1 offer.';

if (isPlaceholderError) {
  angle = 'Malformed Dynamic Creative Template';
  usp = 'None detectable in unparsed template creative.';
  hScore = 0.0; mScore = 0.0; vScore = 0.0; aScore = 1.0; spScore = 0.0; cScore = 5.0; eScore = 0.0; dScore = 0.0;
  painPoint = 'Unclear due to missing product substitution values.';
  valueProp = 'Missing - template variables remained unresolved during ad delivery.';
  techniques = 'None; broken parameter tokens prevent comprehension.';
  strengths = ['Retains standard Call-to-Action button'];
  weaknesses = [
    'Critical Template Placeholder Failure: Contains unrendered variable tokens {{product.name}} and {{product.brand}}.',
    'Zero Informational Value: Copy conveys no educational benefit or pricing offer.',
    'Brand Trust Erosion: Severely harms advertiser credibility in active delivery.'
  ];
  suggestions = [
    'Audit Meta Dynamic Creative catalog feeds to resolve placeholder token keys before publish.',
    'Implement automated copy linting to block publishing ads with curly brace delimiters.'
  ];
  summary = 'Defective dynamic ad placement delivering unresolved template tokens to live users.';
}

const normalized = {
  internal_id: internalId,
  ad_id: adId,
  headline: ad.headline || '',
  primary_text: body,
  hook: hook,
  body: body,
  cta: cta,
  page_name: ad.page_name || 'MySivi',
  landing_page_url: ad.landing_page_url || 'https://sivi.ai',
  media_type: ad.media_type || 'video',
  start_date: ad.start_date || 'Unavailable',
  is_active: ad.is_active !== false,
  ad_library_url: ad.ad_library_url || '',
  image_urls: ad.image_urls || [],
  video_urls: ad.video_urls || [],
  analysis: {
    hook: {
      score: hScore,
      explanation: isPlaceholderError ? 'Placeholder token {{product.brand}} fails as an opening hook.' : `Opening hook '${hook.slice(0, 50)}...' immediately engages learner desire with ₹1 anchor.`
    },
    message_clarity: {
      score: mScore,
      explanation: isPlaceholderError ? 'Unresolved template syntax creates zero coherent message.' : 'Core message is exceptionally clear: AI English tutor available for ₹1.'
    },
    value_prop_usp: {
      score: vScore,
      explanation: isPlaceholderError ? 'No value proposition communicated.' : usp
    },
    target_audience: {
      score: aScore,
      explanation: isPlaceholderError ? 'Unspecified audience targeting due to broken creative.' : 'Regional language speakers seeking judgment-free conversational English fluency.'
    },
    trust_social_proof: {
      score: spScore,
      explanation: isPlaceholderError ? 'Zero trust due to broken template placeholders.' : 'Low financial risk builds initial trial trust; lacks explicit student testimonials.'
    },
    cta_effectiveness: {
      score: cScore,
      explanation: `Direct '${cta}' action routes users to app installation flow.`
    },
    creative_execution: {
      score: eScore,
      explanation: isPlaceholderError ? 'Complete failure in creative production pipeline.' : 'Strong localized copy connecting regional pride with modern conversational AI.'
    },
    differentiation: {
      score: dScore,
      explanation: isPlaceholderError ? 'No unique value delivered.' : 'AI English tutoring in native regional languages at ₹1 micro-trial.'
    },
    customer_pain_point: painPoint,
    value_proposition: valueProp,
    usp: usp,
    marketing_angle: angle,
    persuasion_techniques: techniques,
    strengths: strengths,
    weaknesses: weaknesses,
    improvement_suggestions: suggestions,
    creative_summary: summary
  }
};

// Backwards compatibility reference
normalized.ad = {
  internal_id: normalized.internal_id,
  ad_id: normalized.ad_id,
  headline: normalized.headline,
  primary_text: normalized.primary_text,
  hook: normalized.hook,
  body: normalized.body,
  cta: normalized.cta,
  page_name: normalized.page_name,
  landing_page_url: normalized.landing_page_url,
  media_type: normalized.media_type,
  start_date: normalized.start_date,
  is_active: normalized.is_active,
  ad_library_url: normalized.ad_library_url,
  image_urls: normalized.image_urls,
  video_urls: normalized.video_urls
};

return [{ json: normalized }];

// Validate & Structure Ad Analysis: Enforce strict Normalized Data Contract
const inputItem = $input.first().json;

// Retrieve ad context from current loop batch or input
let currentAd = inputItem.ad || (inputItem.internal_id && inputItem.headline ? inputItem : null);
if (!currentAd) {
  try {
    currentAd = $('Loop Over Ad Creatives').item.json;
  } catch (e) {
    try {
      currentAd = $('Loop Over Ad Creatives').first().json;
    } catch (e2) {
      currentAd = {};
    }
  }
}
currentAd = currentAd || {};

// If input is already normalized by Heuristic Analyzer and has valid nested analysis
if (inputItem.analysis && inputItem.analysis.hook && typeof inputItem.analysis.hook.score === 'number' && inputItem.hook) {
  // Ensure ad sub-object is populated for full backwards compatibility
  if (!inputItem.ad) {
    inputItem.ad = {
      internal_id: inputItem.internal_id,
      ad_id: inputItem.ad_id,
      headline: inputItem.headline,
      hook: inputItem.hook,
      primary_text: inputItem.primary_text,
      body: inputItem.body || inputItem.primary_text,
      cta: inputItem.cta
    };
  }
  return [{ json: inputItem }];
}

// Parse Gemini API candidates response or generic JSON
let parsed = {};
if (inputItem.candidates && inputItem.candidates[0]?.content?.parts?.[0]?.text) {
  const rawText = inputItem.candidates[0].content.parts[0].text;
  const cleanJson = rawText.replace(/^```json\s*/m, '').replace(/^```\s*/m, '').trim();
  try {
    parsed = JSON.parse(cleanJson);
  } catch (err) {
    throw new Error(`Failed to parse Gemini response as JSON: ${err.message}. Raw text: ${rawText.slice(0, 150)}`);
  }
} else if (inputItem.analysis) {
  parsed = inputItem;
} else {
  parsed = inputItem;
}

const parsedAnalysis = parsed.analysis || parsed;
const rubricScores = parsed.rubric_scores || parsedAnalysis.rubric_scores || {};
const rubricExpls = parsed.rubric_explanations || parsed.scoring_explanations || parsedAnalysis.rubric_explanations || {};

// Helper to extract dimension as { score, explanation }
function extractDim(primaryKey, altKey, defaultScore, fallbackExpl) {
  let score = null;
  let explanation = '';

  // 1. Direct object format: analysis[key] = { score, explanation }
  const pObj = parsedAnalysis[primaryKey];
  const aObj = parsedAnalysis[altKey];
  if (pObj && typeof pObj === 'object' && pObj.score !== undefined) {
    score = pObj.score;
    explanation = pObj.explanation || '';
  } else if (aObj && typeof aObj === 'object' && aObj.score !== undefined) {
    score = aObj.score;
    explanation = aObj.explanation || '';
  }

  // 2. Score from rubricScores map
  if (score === null || score === undefined) {
    if (rubricScores[primaryKey] !== undefined) score = rubricScores[primaryKey];
    else if (rubricScores[altKey] !== undefined) score = rubricScores[altKey];
  }

  // 3. Fallback direct number on parsedAnalysis
  if (score === null || score === undefined) {
    if (typeof parsedAnalysis[primaryKey] === 'number') score = parsedAnalysis[primaryKey];
    else if (typeof parsedAnalysis[altKey] === 'number') score = parsedAnalysis[altKey];
  }

  // If still missing, throw descriptive error if defaultScore is null
  if (score === null || score === undefined || isNaN(Number(score))) {
    if (defaultScore === null) {
      throw new Error(`Advertisement ${currentAd.internal_id || 'unknown'}: Missing required score for dimension '${primaryKey}'`);
    }
    score = defaultScore;
  }

  score = Number(score);
  if (score < 0 || score > 10) {
    throw new Error(`Advertisement ${currentAd.internal_id || 'unknown'}: Score for '${primaryKey}' (${score}) is out of bounds [0, 10]`);
  }

  // Extract explanation
  if (!explanation) {
    if (rubricExpls[primaryKey]) explanation = String(rubricExpls[primaryKey]);
    else if (rubricExpls[altKey]) explanation = String(rubricExpls[altKey]);
    else explanation = fallbackExpl || `Assessment for ${primaryKey}.`;
  }

  return {
    score: Math.round(score * 100) / 100,
    explanation: String(explanation)
  };
}

const hookText = currentAd.hook || parsed.hook || parsedAnalysis.hook || currentAd.headline || 'No hook detected';
const bodyText = currentAd.primary_text || currentAd.body || parsed.body || parsed.primary_text || '';
const headlineText = currentAd.headline || parsed.headline || '';
const ctaText = currentAd.cta || parsed.cta || 'Install now';
const internalId = currentAd.internal_id || parsed.internal_id || 'MYSIVI-AD-001';
const adId = String(currentAd.ad_id || currentAd.ad_archive_id || parsed.ad_id || '');

const normalizedRecord = {
  internal_id: internalId,
  ad_id: adId,
  headline: headlineText,
  primary_text: bodyText,
  hook: hookText,
  body: bodyText,
  cta: ctaText,
  page_name: currentAd.page_name || 'MySivi',
  landing_page_url: currentAd.landing_page_url || 'https://sivi.ai',
  media_type: currentAd.media_type || 'video',
  start_date: currentAd.start_date || 'Unavailable',
  is_active: currentAd.is_active !== false,
  ad_library_url: currentAd.ad_library_url || '',
  image_urls: currentAd.image_urls || [],
  video_urls: currentAd.video_urls || [],
  analysis: {
    hook: extractDim('hook', 'hook_effectiveness', 8.0, 'Assessment of opening hook attention and relevance.'),
    message_clarity: extractDim('message_clarity', 'clarity', 8.5, 'Assessment of clarity of the primary value proposition.'),
    value_prop_usp: extractDim('value_prop_usp', 'value_prop', 8.0, 'Assessment of uniqueness and competitiveness of the offer.'),
    target_audience: extractDim('target_audience', 'target_audience_relevance', 8.5, 'Assessment of demographic and psychographic targeting.'),
    trust_social_proof: extractDim('trust_social_proof', 'trust', 6.0, 'Assessment of credibility, trust signals, and social proof.'),
    cta_effectiveness: extractDim('cta_effectiveness', 'cta', 7.5, 'Assessment of call-to-action clarity and friction level.'),
    creative_execution: extractDim('creative_execution', 'execution', 8.0, 'Assessment of formatting, language nuance, and presentation.'),
    differentiation: extractDim('differentiation', 'uniqueness', 8.0, 'Assessment of distinctiveness vs competing solutions.'),

    // Preserve qualitative dimensions
    customer_pain_point: parsed.customer_pain_point || parsedAnalysis.customer_pain_point || 'English speaking hesitation and lack of private practice environment.',
    value_proposition: parsed.value_proposition || parsedAnalysis.value_proposition || 'Private, AI-guided conversational English practice at ₹1.',
    usp: parsed.usp || parsedAnalysis.usp || 'Localized mother-tongue AI conversational tutoring.',
    marketing_angle: parsed.marketing_angle || parsedAnalysis.marketing_angle || 'Low-Barrier ₹1 Trial',
    persuasion_techniques: parsed.persuasion_techniques || parsedAnalysis.persuasion_techniques || 'Price anchoring, mother-tongue comfort, and instant progress promise.',
    strengths: Array.isArray(parsed.strengths) ? parsed.strengths : (Array.isArray(parsedAnalysis.strengths) ? parsedAnalysis.strengths : ['Clear value proposition']),
    weaknesses: Array.isArray(parsed.weaknesses) ? parsed.weaknesses : (Array.isArray(parsedAnalysis.weaknesses) ? parsedAnalysis.weaknesses : ['Needs verified social proof']),
    improvement_suggestions: Array.isArray(parsed.improvement_suggestions) ? parsed.improvement_suggestions : (Array.isArray(parsedAnalysis.improvement_suggestions) ? parsedAnalysis.improvement_suggestions : ['Add student video testimonials']),
    creative_summary: parsed.creative_summary || parsedAnalysis.creative_summary || 'Acquisition creative for MySivi English speaking application.'
  }
};

// Full backwards compatibility sub-object
normalizedRecord.ad = {
  internal_id: normalizedRecord.internal_id,
  ad_id: normalizedRecord.ad_id,
  headline: normalizedRecord.headline,
  primary_text: normalizedRecord.primary_text,
  hook: normalizedRecord.hook,
  body: normalizedRecord.body,
  cta: normalizedRecord.cta,
  page_name: normalizedRecord.page_name,
  landing_page_url: normalizedRecord.landing_page_url,
  media_type: normalizedRecord.media_type,
  start_date: normalizedRecord.start_date,
  is_active: normalizedRecord.is_active,
  ad_library_url: normalizedRecord.ad_library_url,
  image_urls: normalizedRecord.image_urls,
  video_urls: normalizedRecord.video_urls
};

return [{ json: normalizedRecord }];

// Aggregate Validated Advertisements: Read completed iterations from Loop Done output
const rawItems = $input.all();
let items = rawItems.map(it => it.json || it);

const hasAnalysis = (rec) => rec && rec.analysis && typeof rec.analysis === 'object' && rec.internal_id;

let analyzedItems = items.filter(hasAnalysis);

// Fallback: If $input.all() does not carry the validated records, check $('Validate & Structure Ad Analysis').all()
if (analyzedItems.length === 0) {
  try {
    const validatedAll = $('Validate & Structure Ad Analysis').all();
    if (validatedAll && validatedAll.length > 0) {
      const candidates = validatedAll.map(it => it.json || it).filter(hasAnalysis);
      if (candidates.length > 0) {
        analyzedItems = candidates;
      }
    }
  } catch (e) {
    // Cross-node access unavailable or not supported
  }
}

// Deduplicate by internal_id
const seenIds = new Set();
const uniqueAnalyzed = [];

for (const ad of analyzedItems) {
  if (!seenIds.has(ad.internal_id)) {
    seenIds.add(ad.internal_id);
    uniqueAnalyzed.push(ad);
  }
}

// Strict Validation: Zero analyzed records
if (uniqueAnalyzed.length === 0) {
  throw new Error(
    "Aggregate Validated Advertisements: Received 0 completed advertisement analyses. " +
    "Ensure Loop Over Ad Creatives completed all iterations and Validate & Structure Ad Analysis executed."
  );
}

// Strict Validation: Exactly 4 unique analyzed records
if (uniqueAnalyzed.length !== 4) {
  throw new Error(
    `Aggregate Validated Advertisements: Expected 4 unique analyzed advertisements, but found ${uniqueAnalyzed.length}. ` +
    `Found IDs: [${uniqueAnalyzed.map(a => a.internal_id).join(', ')}]`
  );
}

// Strict Validation: Verify required core ad fields
for (const ad of uniqueAnalyzed) {
  if (!ad.headline || !ad.hook) {
    throw new Error(`Aggregate Validated Advertisements: Ad '${ad.internal_id}' is missing required fields (headline, hook).`);
  }
}

return uniqueAnalyzed.map(ad => ({ json: ad }));

// Pre-Scoring Validation: Enforces strict data integrity before ranking
const items = $input.all().map(item => item.json);

if (!Array.isArray(items) || items.length === 0) {
  throw new Error("Validate Scoring Input: Received zero advertisements for scoring.");
}

// 1. Verify exactly four unique advertisement records are present
if (items.length !== 4) {
  throw new Error(`Validate Scoring Input: Expected exactly 4 unique advertisement records, but received ${items.length}.`);
}

const seenIds = new Set();
const requiredDimensions = [
  'hook',
  'message_clarity',
  'value_prop_usp',
  'target_audience',
  'trust_social_proof',
  'cta_effectiveness',
  'creative_execution',
  'differentiation'
];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const id = item.internal_id;

  if (!id) {
    throw new Error(`Validate Scoring Input: Item at index ${i} is missing 'internal_id'.`);
  }

  // Verify no duplicate ads
  if (seenIds.has(id)) {
    throw new Error(`Validate Scoring Input: Duplicate advertisement detected: '${id}'.`);
  }
  seenIds.add(id);

  // Verify core ad fields
  if (!item.headline) {
    throw new Error(`Validate Scoring Input: Ad '${id}' is missing 'headline'.`);
  }
  if (!item.hook) {
    throw new Error(`Validate Scoring Input: Ad '${id}' is missing 'hook'.`);
  }

  // Verify analysis object exists
  if (!item.analysis || typeof item.analysis !== 'object') {
    throw new Error(`Validate Scoring Input: Ad '${id}' is missing 'analysis' object. Cannot score incomplete analysis.`);
  }

  // Verify all eight scoring dimensions exist and are numeric between 0 and 10
  const an = item.analysis;
  for (const dim of requiredDimensions) {
    const dimObj = an[dim];
    if (!dimObj) {
      throw new Error(`Validate Scoring Input: Ad '${id}' is missing scoring dimension '${dim}'.`);
    }
    const scoreVal = (typeof dimObj === 'object' && dimObj !== null) ? dimObj.score : dimObj;
    if (scoreVal === undefined || scoreVal === null || isNaN(Number(scoreVal))) {
      throw new Error(`Validate Scoring Input: Ad '${id}' dimension '${dim}' has missing or non-numeric score: ${JSON.stringify(scoreVal)}.`);
    }
    const numScore = Number(scoreVal);
    if (numScore < 0 || numScore > 10) {
      throw new Error(`Validate Scoring Input: Ad '${id}' dimension '${dim}' score (${numScore}) is out of bounds [0, 10].`);
    }
  }
}

// All checks passed: forward verified items directly to scoring node
return items.map(item => ({ json: item }));

// Score, Rank & Synthesize Intelligence: Consumes Normalized Data Contract
let allAnalyzed = [];

// 1. Gather results directly from validated input (Validate Scoring Input)
allAnalyzed = $input.all().map(item => item.json).filter(Boolean);

// Fallback: If direct input was empty, try cross-node query
if (!allAnalyzed || allAnalyzed.length === 0) {
  try {
    const loopResults = $('Validate & Structure Ad Analysis').all();
    if (Array.isArray(loopResults) && loopResults.length > 0) {
      allAnalyzed = loopResults.map(item => item.json).filter(Boolean);
