}

// 2. Strict validation of aggregated analysis items
if (!allAnalyzed || allAnalyzed.length === 0) {
  throw new Error("Scoring stage received zero items. Ensure Loop Over Ad Creatives has completed and Validate & Structure Ad Analysis has run.");
}

for (let i = 0; i < allAnalyzed.length; i++) {
  const item = allAnalyzed[i];
  const id = item.internal_id || (item.ad && item.ad.internal_id) || `Item[${i}]`;
  if (!item.analysis || typeof item.analysis !== 'object') {
    throw new Error(`Advertisement ${id} is missing 'analysis' object. Cannot score incomplete analysis.`);
  }
  const hookText = item.hook || (item.ad && item.ad.hook);
  if (hookText === undefined || hookText === null) {
    throw new Error(`Advertisement ${id} is missing 'hook' field.`);
  }
}

// 3. Mathematical 100-point Rubric Weights
const weights = {
  hook: 20,
  message_clarity: 15,
  value_prop_usp: 15,
  target_audience: 10,
  trust_social_proof: 10,
  cta_effectiveness: 10,
  creative_execution: 10,
  differentiation: 10
};

// 4. Calculate total score and score breakdown
const scoredAds = allAnalyzed.map(entry => {
  const an = entry.analysis || {};

  // Safe score reader supporting normalized { score, explanation } and legacy fallbacks
  const getScore = (key, altKey) => {
    const field = an[key] || an[altKey];
    let val = undefined;
    if (field && typeof field === 'object' && field.score !== undefined) {
      val = field.score;
    } else if (typeof field === 'number') {
      val = field;
    } else if (entry.rubric_scores && entry.rubric_scores[key] !== undefined) {
      val = entry.rubric_scores[key];
    } else if (entry.rubric_scores && entry.rubric_scores[altKey] !== undefined) {
      val = entry.rubric_scores[altKey];
    }

    if (val === undefined || val === null || isNaN(Number(val))) {
      throw new Error(`Ad ${entry.internal_id || 'unknown'}: Missing or invalid score for dimension '${key}'`);
    }
    val = Number(val);
    if (val < 0 || val > 10) {
      throw new Error(`Ad ${entry.internal_id || 'unknown'}: Score for '${key}' (${val}) out of bounds [0, 10]`);
    }
    return val;
  };

  const h = getScore('hook', 'hook_effectiveness');
  const m = getScore('message_clarity', 'clarity');
  const v = getScore('value_prop_usp', 'value_prop');
  const t = getScore('target_audience', 'target_audience_relevance');
  const sp = getScore('trust_social_proof', 'trust');
  const c = getScore('cta_effectiveness', 'cta');
  const e = getScore('creative_execution', 'execution');
  const d = getScore('differentiation', 'uniqueness');

  const total = (
    (h * weights.hook) +
    (m * weights.message_clarity) +
    (v * weights.value_prop_usp) +
    (t * weights.target_audience) +
    (sp * weights.trust_social_proof) +
    (c * weights.cta_effectiveness) +
    (e * weights.creative_execution) +
    (d * weights.differentiation)
  ) / 10.0;

  const roundedTotal = Math.round(total * 100) / 100;

  // Ensure ad sub-object is populated for full compatibility
  const adObj = entry.ad || {
    internal_id: entry.internal_id,
    ad_id: entry.ad_id,
    headline: entry.headline,
    hook: entry.hook,
    primary_text: entry.primary_text || entry.body,
    body: entry.body || entry.primary_text,
    cta: entry.cta,
    page_name: entry.page_name || 'MySivi',
    landing_page_url: entry.landing_page_url || 'https://sivi.ai',
    media_type: entry.media_type || 'video',
    start_date: entry.start_date || 'Unavailable',
    is_active: entry.is_active !== false,
    ad_library_url: entry.ad_library_url || '',
    image_urls: entry.image_urls || [],
    video_urls: entry.video_urls || []
  };

  const scoreBreakdown = {
    hook_effectiveness: h,
    message_clarity: m,
    value_prop_usp: v,
    target_audience_relevance: t,
    trust_social_proof: sp,
    cta_effectiveness: c,
    creative_execution: e,
    differentiation: d,
    total_score: roundedTotal
  };

  return {
    ...entry,
    internal_id: entry.internal_id || adObj.internal_id,
    headline: entry.headline || adObj.headline,
    hook: entry.hook || adObj.hook,
    primary_text: entry.primary_text || adObj.primary_text,
    body: entry.body || adObj.body,
    cta: entry.cta || adObj.cta,
    ad: adObj,
    analysis: entry.analysis,
    score: scoreBreakdown,
    rubric_scores: scoreBreakdown
  };
});

// 5. Multi-tier sort with documented tie-breakers
scoredAds.sort((a, b) => {
  const scoreDiff = b.score.total_score - a.score.total_score;
  if (Math.abs(scoreDiff) > 0.001) return scoreDiff;
  const hDiff = (b.score.hook_effectiveness || 0) - (a.score.hook_effectiveness || 0);
  if (Math.abs(hDiff) > 0.001) return hDiff;
  const vDiff = (b.score.value_prop_usp || 0) - (a.score.value_prop_usp || 0);
  if (Math.abs(vDiff) > 0.001) return vDiff;
  return (b.score.message_clarity || 0) - (a.score.message_clarity || 0);
});

