scoredAds.forEach((item, index) => {
  if (index === 0) {
    item.rank = 1;
    item.is_best_creative = true;
  } else {
    const prev = scoredAds[index - 1];
    const isTied = (Math.abs(item.score.total_score - prev.score.total_score) < 0.001) &&
                   (Math.abs((item.score.hook_effectiveness || 0) - (prev.score.hook_effectiveness || 0)) < 0.001) &&
                   (Math.abs((item.score.value_prop_usp || 0) - (prev.score.value_prop_usp || 0)) < 0.001);
    if (isTied) {
      item.rank = prev.rank;
      item.is_best_creative = prev.is_best_creative;
    } else {
      item.rank = index + 1;
      item.is_best_creative = false;
    }
  }
});

